(function(){
  var $=function(id){return document.getElementById(id)};
  var money=function(n){return n.toLocaleString(undefined,{maximumFractionDigits:0})};
  function calc(){
    var age=+$('age').value||0, rage=+$('rage').value||0;
    var have=+$('have').value||0, add=+$('add').value||0;
    var pre=(+$('pre').value||0)/100, post=(+$('post').value||0)/100;
    var span=+$('span').value||1, infl=(+$('infl').value||0)/100;
    var years=rage-age;
    if(years<=0){ $('note').textContent='Retirement age must be later than your current age.';
      $('pot').textContent='0'; $('income').textContent='0'; $('real').textContent='0';
      $('brk').innerHTML=''; if(window.WT) WT.resize(); return; }
    var months=Math.round(years*12), mr=pre/12;
    // Grow what is already saved, then the monthly deposits on top.
    var pot = mr===0 ? have + add*months
      : have*Math.pow(1+mr,months) + add*((Math.pow(1+mr,months)-1)/mr);
    // Drawing down: an annuity paying a level amount for the whole retirement.
    var income = post===0 ? pot/span
      : pot*post/(1-Math.pow(1+post,-span));
    // What that income is worth in money you can compare with today.
    var real = income/Math.pow(1+infl,years);
    var contributed = have + add*months;
    $('pot').textContent=money(pot);
    $('income').textContent=money(income);
    $('real').textContent=money(real);
    $('brk').innerHTML=
      '<div><span>Years until you retire</span><b>'+years+'</b></div>'+
      '<div><span>You will have paid in</span><b>'+money(contributed)+'</b></div>'+
      '<div><span>Growth on top</span><b>'+money(pot-contributed)+'</b></div>'+
      '<div><span>Income per month</span><b>'+money(income/12)+'</b></div>'+
      '<div><span>Total drawn over '+span+' years</span><b>'+money(income*span)+'</b></div>';
    $('note').textContent='This assumes a level income for '+span+
      ' years and that the pot keeps earning '+(post*100).toFixed(1)+
      '% while you draw from it. The last figure adjusts for '+(infl*100).toFixed(1)+
      '% inflation, so it is comparable with what money buys today.';
    if(window.WT) WT.resize();
  }
  ['age','rage','have','add','pre','post','span','infl'].forEach(function(id){
    $(id).addEventListener('input',calc);
  });
  $('go').addEventListener('click',calc);
  $('copy').addEventListener('click',function(){
    var ok=WT.copy('Pot at retirement: '+$('pot').textContent+
      '. Yearly income: '+$('income').textContent+
      ' ('+$('real').textContent+" in today's money).");
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy result'},1400);
  });
  calc();
})();
